sp_widget.client_script:
api.controller = function ($scope, $timeout, $window) {
  var c = this;

  c.submitting = false;
  c.submitted = false;

  // Visit form data
  c.visit = {
    visitor_name: '',
    visitor_email: '',
    visitor_phone: '',
    visitor_company: '',
    host: '',
    purpose: '',
    visit_date: '',
    notes: ''
  };

  // Guest list — start with one empty guest
  c.guests = [
    { first_name: '', last_name: '', email: '', phone: '', company: '' }
  ];

  // sn-record-picker config for host field
  c.hostTable = 'sys_user';
  c.hostDisplayField = 'name';
  c.hostSearchFields = 'name,email';
  c.hostValueField = 'sys_id';

  // Validation errors tracking
  c.errors = {};

  c.addGuest = function () {
    c.guests.push({ first_name: '', last_name: '', email: '', phone: '', company: '' });
  };

  c.removeGuest = function (index) {
    if (c.guests.length > 1) {
      c.guests.splice(index, 1);
    }
  };

  c.validate = function () {
    c.errors = {};
    var valid = true;

    if (!c.visit.visitor_name) {
      c.errors.visitor_name = 'Visitor name is required.';
      valid = false;
    }
    if (!c.visit.host) {
      c.errors.host = 'Host is required.';
      valid = false;
    }
    if (!c.visit.visit_date) {
      c.errors.visit_date = 'Visit date is required.';
      valid = false;
    }
    if (c.guests.length === 0) {
      c.errors.guests = 'At least one guest is required.';
      valid = false;
    }
    for (var i = 0; i < c.guests.length; i++) {
      if (!c.guests[i].first_name) {
        c.errors['guest_first_' + i] = 'First name is required.';
        valid = false;
      }
      if (!c.guests[i].last_name) {
        c.errors['guest_last_' + i] = 'Last name is required.';
        valid = false;
      }
    }

    return valid;
  };

  c.submit = function () {
    if (!c.validate()) {
      c.data.errorMsg = 'Please correct the errors below before submitting.';
      return;
    }

    c.submitting = true;
    c.data.errorMsg = '';

    c.server.get({
      action: 'submit',
      visitData: c.visit,
      guests: c.guests
    }).then(function (r) {
      c.submitting = false;
      if (r.data.success) {
        c.submitted = true;
        c.data.successMsg = r.data.successMsg;
        c.data.visitNumber = r.data.visitNumber;

        // Redirect to home after 3 seconds
        $timeout(function () {
          $window.location.href = '?id=x_1085196_visita_0_home';
        }, 3000);
      } else {
        c.data.errorMsg = r.data.errorMsg || 'An error occurred during submission.';
      }
    }, function () {
      c.submitting = false;
      c.data.errorMsg = 'Server communication error. Please try again.';
    });
  };
};

sp_widget.css:
/* Visit Request Form Widget — using Coral theme variables */

/* Form input styling (from css.md Section 8) */
.sp-input {
  height: $input-height-base;
  border: 1px solid $border-tertiary;
  border-radius: $border-radius-base;
  padding: 0 12px;
  font-size: $font-size-base;
  color: $text-color;
  background: $background-primary;
  transition: border-color 0.15s, box-shadow 0.15s;
  width: 100%;
  &:focus {
    border-color: $brand-primary;
    box-shadow: 0 0 0 3px rgba($brand-primary, 0.15);
    outline: none;
  }
}
.has-error .sp-input {
  border-color: $brand-danger;
}

/* Textarea (from css.md Section 8) */
.sp-textarea {
  border-radius: $border-radius-base;
  border: 1px solid $border-tertiary;
  padding: 12px;
  font-size: $font-size-base;
  color: $text-color;
  background: $background-primary;
  resize: vertical;
  min-height: 100px;
  transition: border-color 0.15s;
  &:focus {
    border-color: $brand-primary;
    box-shadow: 0 0 0 3px rgba($brand-primary, 0.15);
    outline: none;
  }
}
.has-error .sp-textarea {
  border-color: $brand-danger;
}

/* Section title */
.sp-section-title {
  font-size: $font-size-large;
  font-weight: 600;
  color: $text-color;
  margin-top: 24px;
  margin-bottom: 8px;
  .glyphicon {
    margin-right: 8px;
    color: $brand-primary;
    font-size: 16px;
  }
}

/* Guest row card */
.sp-guest-row {
  background: $background-secondary;
  border: 1px solid $border-tertiary;
  border-radius: $border-radius-base;
  padding: 16px;
  margin-bottom: 16px;
}
.sp-guest-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 12px;
  strong {
    font-size: $font-size-base;
    color: $text-color;
  }
}

/* Add guest row */
.sp-add-guest-row {
  margin-top: 8px;
  margin-bottom: 24px;
}

/* Button styles (from css.md Section 9) */
.sp-btn-primary,
.sp-btn-secondary {
  height: 44px;
  padding: 0 20px;
  border-radius: $border-radius-base;
  font-size: $font-size-base;
  font-weight: 500;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  transition: background 0.15s, box-shadow 0.15s;
  cursor: pointer;
  border: none;
}
.sp-btn-primary {
  background: $brand-primary;
  color: $btn-primary-color;
  &:hover:not(:disabled) {
    background: $brand-primary-dark;
    box-shadow: 0 2px 8px rgba($brand-primary, 0.3);
    color: $btn-primary-color;
  }
  &:disabled {
    opacity: 0.55;
    cursor: not-allowed;
  }
}
.sp-btn-secondary {
  background: $background-primary;
  border: 1px solid $border-tertiary;
  color: $text-color;
  text-decoration: none;
  &:hover {
    background: $background-secondary;
    text-decoration: none;
    color: $text-color;
  }
}
.sp-btn-group {
  display: flex;
  gap: 8px;
  align-items: center;
  margin-top: 24px;
  flex-wrap: wrap;
}

/* Success state */
.sp-success-state {
  padding: 64px 24px;
}
.sp-success-icon {
  font-size: 48px;
  display: block;
  margin-bottom: 16px;
}

/* Spinner animation (from css.md Section 9) */
@keyframes sp-spin {
  to { transform: rotate(360deg); }
}
.sp-spin {
  animation: sp-spin 0.8s linear infinite;
}

sp_widget.script:
(function () {
  data.success = false;
  data.errorMsg = '';
  data.successMsg = '';
  data.visitNumber = '';
  data.userName = '';

  // Get current user display name for the form
  var userGr = new GlideRecord('sys_user');
  if (userGr.get(gs.getUserID())) {
    data.userName = userGr.getDisplayValue('name') + '';
  }

  // Handle form submission
  if (input && input.action === 'submit') {
    try {
      var visitData = input.visitData;
      var guests = input.guests;

      // Server-side validation
      if (!visitData.visitor_name || !visitData.host || !visitData.visit_date) {
        data.errorMsg = 'Please fill in all required fields (Name, Host, Visit Date).';
        return;
      }
      if (!guests || guests.length === 0) {
        data.errorMsg = 'At least one guest is required.';
        return;
      }
      for (var g = 0; g < guests.length; g++) {
        if (!guests[g].first_name || !guests[g].last_name) {
          data.errorMsg = 'Each guest must have a first name and last name.';
          return;
        }
      }

      // Create Visit record using GlideRecord (bypasses ACLs)
      var visitGr = new GlideRecord('x_1085196_visita_0_visit');
      visitGr.initialize();
      visitGr.setValue('visitor_name', visitData.visitor_name);
      visitGr.setValue('visitor_email', visitData.visitor_email || '');
      visitGr.setValue('visitor_phone', visitData.visitor_phone || '');
      visitGr.setValue('visitor_company', visitData.visitor_company || '');
      visitGr.setValue('host', visitData.host);
      visitGr.setValue('purpose', visitData.purpose || '');
      visitGr.setValue('visit_date', visitData.visit_date);
      visitGr.setValue('notes', visitData.notes || '');
      visitGr.setValue('requested_by', gs.getUserID());
      visitGr.setValue('status', 'pending');
      visitGr.setValue('number_of_guests', guests.length);

      var visitId = visitGr.insert();

      if (!visitId) {
        data.errorMsg = 'Failed to create visit record. Please try again.';
        return;
      }

      // Create Guest records
      for (var i = 0; i < guests.length; i++) {
        var guestGr = new GlideRecord('x_1085196_visita_0_guest');
        guestGr.initialize();
        guestGr.setValue('visit', visitId);
        guestGr.setValue('first_name', guests[i].first_name);
        guestGr.setValue('last_name', guests[i].last_name);
        guestGr.setValue('email', guests[i].email || '');
        guestGr.setValue('phone', guests[i].phone || '');
        guestGr.setValue('company', guests[i].company || '');
        guestGr.setValue('status', 'pending');
        guestGr.insert();
      }

      data.success = true;
      data.visitNumber = visitGr.getValue('number') + '';
      data.successMsg = 'Visit request ' + data.visitNumber + ' has been submitted successfully!';

    } catch (e) {
      gs.error('Visit Request Form error: ' + e.message);
      data.errorMsg = 'An unexpected error occurred. Please try again.';
    }
    return;
  }
})();
